/**
 * Links a Supabase Auth user to a public.users row with the super_admin role.
 *
 * ADR-005 Decision 3: public.users.id holds the same value as auth.users.id, so
 * the CRM record cannot exist before the Auth identity does. Create the Auth
 * user first — Supabase Dashboard > Authentication > Users > Add user — then run
 * this to give them a CRM profile.
 *
 * Deliberately does NOT create the Auth user or set a password. The admin
 * password should be chosen by a person and kept in a password manager, not
 * generated by tooling and left in a terminal history.
 *
 * Usage:
 *   node scripts/link-super-admin.mjs you@example.com "Your Name"
 *
 * Idempotent: running it twice updates the existing row rather than failing.
 */
import postgres from "postgres";
import { config } from "dotenv";

config({ path: ".env.local" });

const [email, name] = process.argv.slice(2);

if (!email) {
  console.error("Usage: node scripts/link-super-admin.mjs <email> [name]");
  process.exit(1);
}

const sql = postgres(process.env.DATABASE_URL, { prepare: false, connect_timeout: 20, max: 1 });

try {
  const authRows = await sql`
    select id, email, email_confirmed_at is not null as confirmed
    from auth.users
    where lower(email) = lower(${email})
    limit 1`;

  const authUser = authRows[0];

  if (!authUser) {
    console.error(
      `No Supabase Auth user found for ${email}.\n` +
        `Create one first: Supabase Dashboard > Authentication > Users > Add user.\n` +
        `Tick "Auto Confirm User" so the account can sign in immediately.`,
    );
    process.exit(1);
  }

  const [row] = await sql`
    insert into public.users (id, name, email, role, status)
    values (
      ${authUser.id},
      ${name ?? email.split("@")[0]},
      ${authUser.email},
      'super_admin',
      'active'
    )
    on conflict (id) do update
      set role = 'super_admin',
          status = 'active',
          name = excluded.name,
          email = excluded.email,
          updated_at = now()
    returning id, name, email, role, status`;

  console.log(
    JSON.stringify({ linked: true, authUserConfirmed: authUser.confirmed, user: row }, null, 2),
  );

  if (!authUser.confirmed) {
    console.warn(
      "\nWARNING: this Auth user is not confirmed and will not be able to sign in.\n" +
        "Confirm them in the Supabase dashboard, or recreate with Auto Confirm enabled.",
    );
  }
} catch (error) {
  console.error(String(error.message ?? error));
  process.exit(1);
} finally {
  await sql.end({ timeout: 5 });
}
